// spec: specs/whatsapp-seller.md (1.3) · кейс: .qa/tests/whatsapp-seller/WA-DISC-01.md
// seed: tests/seed.user.spec.ts · прод, только чтение: кнопки WhatsApp не нажимаются.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, readSellerMessages, LOAD, WWW } from './whatsapp.helpers';

test.use({ storageState: '../auth/user.json' });

// Дискретное объявление (F-25). Если снято/перестало быть дискретным — заменить (см. кейс WA-DISC-01).
const DISCRETE_ID = '4a91620b-b4ef-4785-bb20-d0d40a67f977';
const DISCRETE_TITLE = /משחקייה מצליחה/;
const REGULAR_ID = '4d62fda8-629a-4ad5-9913-3f925cbbb1d1';

/** Главная кнопка WhatsApp продавцу на странице объявления — <button>; ссылки похожих объявлений — <a>, не считаются. */
const mainWhatsAppButton = (page: import('@playwright/test').Page) => page.locator('button').filter({ hasText: 'WhatsApp' });

test.describe('WhatsApp למוכר — дискретное объявление', () => {
  test('Дискретное объявление: на странице нет кнопки WhatsApp продавцу (контроль — обычное есть) #e8bbad #1d84d2 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);

    await page.goto(`/businessdetail?id=${REGULAR_ID}`);
    await expect(mainWhatsAppButton(page).first(), 'контроль: у обычного объявления кнопка WhatsApp есть').toBeVisible(LOAD);

    await page.goto(`/businessdetail?id=${DISCRETE_ID}`);
    await expect(page.getByText(DISCRETE_TITLE).first(), 'дискретное объявление отрисовано').toBeVisible(LOAD);
    await expect(mainWhatsAppButton(page), 'у дискретного объявления кнопки WhatsApp нет').toHaveCount(0);
  });

  test('Дискретное объявление: в /search нет сообщения продавцу с его ссылкой #e8bbad #1d84d2 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await page.goto(WWW + '/search');
    await expect(page.locator(`a[href*="businessdetail?id=${DISCRETE_ID}"]`).first(), 'карточка дискретного объявления в выдаче').toBeAttached(LOAD);
    const messages = await readSellerMessages(page);
    const code = DISCRETE_ID.slice(0, 8);
    expect(messages.filter((m) => m.text.includes(`/b/${code}`) || m.cardId === DISCRETE_ID), 'нет WhatsApp продавцу у дискретного').toHaveLength(0);
  });
});
